def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count opponent cooperation/defection overall and recent
    opp_c = 0
    opp_d = 0
    my_d = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if a == 'D':
            my_d += 1

    # Consecutive opponent defections
    consec_opp_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            consec_opp_d += 1
        else:
            break

    # Consecutive opponent cooperations
    consec_opp_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            consec_opp_c += 1
        else:
            break

    # Recent windows
    w = 8 if n >= 8 else n
    recent_opp_c = 0
    for i in range(n - w, n):
        if history[i][1] == 'C':
            recent_opp_c += 1
    recent_rate = recent_opp_c / float(w)

    total_rate = opp_c / float(n)

    # Very early: cooperate to establish mutual cooperation
    if n < 4:
        return 'C'

    # Endgame: exploit pure cooperators, avoid being suckered
    remaining = 100 - n

    # If opponent almost always defects, defect (rare probe)
    if opp_d >= n - 1 and n >= 5:
        if n % 13 == 0:
            return 'C'
        return 'D'

    # If opponent nearly always cooperates, exploit progressively near the end
    if opp_c >= n - 1 and n >= 8:
        if remaining <= 5:
            return 'D'
        # occasional probe mid-game
        if remaining > 20 and n % 9 == 0:
            return 'D'
        return 'C'

    if remaining <= 2:
        if opp_c * 2 >= n:
            return 'D'
        if history[-1][1] == 'D':
            return 'D'
        return 'C'

    if remaining <= 5:
        if recent_rate >= 0.5:
            return 'D'
        if consec_opp_d >= 2:
            return 'D'
        return 'C'

    # Strong defector: mostly defect, occasional cooperate to probe
    if total_rate <= 0.25:
        if consec_opp_d >= 4:
            return 'D'
        if n % 7 == 0:
            return 'C'
        return 'D'

    # Mostly cooperative opponent: preserve cooperation, punish isolated defections briefly
    if total_rate >= 0.85:
        if consec_opp_d >= 2:
            return 'D'
        if consec_opp_d == 1:
            # brief retaliation but forgive quickly
            if my_d >= 2 and recent_rate >= 0.75:
                return 'C'
            return 'D'
        return 'C'

    # High recent cooperation: cooperate, occasional restraint against being exploited
    if recent_rate >= 0.75:
        if consec_opp_d >= 3:
            return 'D'
        if consec_opp_d == 1:
            return 'D'
        return 'C'

    # Moderate opponent: tit-for-tat with forgiveness to escape retaliation loops
    last_opp = history[-1][1]
    if last_opp == 'C':
        return 'C'

    # Opponent defected last
    if consec_opp_d >= 3:
        # Punish extended chains
        if total_rate >= 0.5 and n % 8 == 0:
            return 'C'
        return 'D'

    if consec_opp_d == 2:
        if total_rate >= 0.6:
            # forgive to break spiral
            return 'C'
        return 'D'

    # consec_opp_d == 1, isolated defection
    if total_rate >= 0.7:
        # brief retaliation then forgive
        if my_d >= 1:
            return 'C'
        return 'D'
    # moderate/low cooperation - retaliate
    if rng.random() < 0.2:
        return 'C'
    return 'D'
